// 클라이언트 패킷 진입점
// (주석 안의 Dispatch 는 클릭 대상이 아니다)
void HandlePacket(Session* sess, Packet* pkt) {
    if (!sess->IsAuthed()) {
        sess->Close("unauthenticated");
        return;
    }

    auto* handler = g_registry.Find(pkt->opcode);
    if (handler == nullptr) {
        LOG_WARN("unknown opcode {}", pkt->opcode);
        return;
    }
    handler->Invoke(sess, pkt);
}

func (h *LoginHandler) Invoke(s *Session, p *Packet) {
	const q = `SELECT id FROM users WHERE token = $1`
	row := h.db.QueryRow(q, p.Token)
	if err := row.Scan(&s.UserID); err != nil {
		s.Close("bad token")
		return
	}
}

impl Handler for LoginHandler {
    fn handle(&self, s: &mut Session) -> Result<()> {
        // 로그인 처리 🚀 (주석 안 handle 은 클릭 대상 아님)
        let token = s.take_token()?;
        self.verify(&token)
    }
}

